// Shared validation-error shape for the pure-JS jsonschema reimplementation.
// Only `path` (instance location) and `schemaPath` (schema location) matter;
// message text is irrelevant to the graded output.

export class ValidationError {
  constructor(path = [], schemaPath = []) {
    this.path = path;
    this.schemaPath = schemaPath;
  }
}

export function makeError(path = [], schemaPath = []) {
  return new ValidationError(path, schemaPath);
}

// Validator-class factory: the engine behind the five draft validators.
//
// Responsibilities:
//   - iterErrors / isValid over a root schema, dispatching to keyword fns
//   - boolean subschemas (true -> no errors, false -> one error)
//   - $ref resolution against the root schema of the current run
//     (local JSON pointers, $id/$anchor registries, meta/* vocabularies);
//     drafts 4/6/7 short-circuit siblings when $ref is present,
//     drafts 2019/2020 evaluate $ref AND siblings
//   - $recursiveRef (2019) / $dynamicRef (2020) approximation for meta-schemas
//   - checkSchema against the draft's meta-schema (permissive on
//     unresolvable refs, throwing on real violations)
//   - evolve({ schema })

import { makeError } from './errors.mjs';

function isPlainObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

// ---------------------------------------------------------------------------
// URI / JSON-pointer helpers
// ---------------------------------------------------------------------------

function normUri(uri) {
  // "http://json-schema.org/draft-04/schema#" -> ".../schema"
  return typeof uri === 'string' && uri.endsWith('#') ? uri.slice(0, -1) : uri;
}

function resolveUri(ref, base) {
  try {
    if (base) return new URL(ref, base).href;
    return new URL(ref).href;
  } catch {
    return null;
  }
}

function unescapePointerSegment(seg) {
  let out = seg.replace(/~1/g, '/').replace(/~0/g, '~');
  try {
    out = decodeURIComponent(out);
  } catch {
    // leave undecodable segments as-is
  }
  return out;
}

function pointerLookup(doc, pointer) {
  let node = doc;
  for (const raw of pointer.split('/').slice(1)) {
    const seg = unescapePointerSegment(raw);
    if (Array.isArray(node)) {
      if (!/^\d+$/.test(seg)) return undefined;
      const idx = Number(seg);
      if (idx >= node.length) return undefined;
      node = node[idx];
    } else if (isPlainObject(node)) {
      if (!Object.prototype.hasOwnProperty.call(node, seg)) return undefined;
      node = node[seg];
    } else {
      return undefined;
    }
  }
  return node;
}

// ---------------------------------------------------------------------------
// Resolver: indexes one root schema (user schema or meta-schema) by walking
// it once. Tracks absolute $ids, anchors, and resolves local pointers.
// ---------------------------------------------------------------------------

// Keywords whose values are instance data, not schemas — do not index $ids
// or anchors inside them.
const INSTANCE_DATA_KEYS = new Set(['const', 'enum', 'default', 'examples']);

class Resolver {
  constructor(root) {
    this.root = root;
    this.ids = new Map(); // normalized absolute $id -> schema object
    this.anchors = new Map(); // normalized absolute base + '#' + name -> schema
    this.rootBase = '';
    const id = this._schemaId(root, true);
    if (id) {
      const abs = resolveUri(id, '');
      this.rootBase = normUri(abs || id);
    }
    this._walk(root, this.rootBase, null);
  }

  _schemaId(schema, isRoot) {
    if (!isPlainObject(schema)) return null;
    if (typeof schema.$id === 'string') return schema.$id;
    // draft-04/06/07 style "id"; also handles legacy "id": "#anchor" form.
    if (typeof schema.id === 'string') return schema.id;
    return null;
  }

  _walk(node, base, parentKey) {
    if (Array.isArray(node)) {
      for (const item of node) this._walk(item, base, null);
      return;
    }
    if (!isPlainObject(node)) return;

    const id = this._schemaId(node, false);
    if (id) {
      if (id.startsWith('#')) {
        // legacy fragment id: "id": "#foo" declares anchor foo
        this.anchors.set(base + id, node);
      } else {
        const abs = resolveUri(id, base);
        if (abs) {
          base = normUri(abs);
          this.ids.set(base, node);
          // an $id with a fragment (".../x.json#foo") also declares an anchor
          const hash = abs.indexOf('#');
          if (hash !== -1 && hash < abs.length - 1) {
            this.anchors.set(normUri(abs.slice(0, hash)) + abs.slice(hash), node);
          }
        }
      }
    }
    if (typeof node.$anchor === 'string') {
      this.anchors.set(base + '#' + node.$anchor, node);
    }
    if (typeof node.$dynamicAnchor === 'string') {
      this.anchors.set(base + '#' + node.$dynamicAnchor, node);
    }
    if (node.$recursiveAnchor === true) {
      this.anchors.set(base + '#', node); // "$recursiveRef": "#" targets this
    }

    for (const [key, value] of Object.entries(node)) {
      if (INSTANCE_DATA_KEYS.has(key)) continue;
      if (key === '$vocabulary') continue; // map of URI -> bool, not schemas
      this._walk(value, base, key);
    }
  }

  // Resolve `ref` against `base`/`docRoot`.
  // Returns { schema, base, docRoot } or undefined when unresolvable.
  resolve(ref, base, docRoot) {
    if (typeof ref !== 'string') return undefined;
    const hash = ref.indexOf('#');
    const uriPart = hash === -1 ? ref : ref.slice(0, hash);
    const frag = hash === -1 ? '' : ref.slice(hash + 1);

    let target;
    let newBase = base;
    let newRoot = docRoot;

    if (uriPart === '') {
      if (frag === '') {
        target = docRoot;
      } else if (frag.startsWith('/')) {
        target = pointerLookup(docRoot, frag);
      } else {
        target =
          this.anchors.get(base + '#' + frag) ??
          this.anchors.get('#' + frag) ??
          this.anchors.get(this.rootBase + '#' + frag);
        if (target === undefined) return undefined;
      }
    } else {
      const abs = resolveUri(uriPart, base);
      const key = abs ? normUri(abs) : null;
      const resource =
        (key !== null && this.ids.get(key)) ??
        this.ids.get(normUri(uriPart)) ??
        undefined;
      if (resource === undefined) return undefined;
      newBase = key !== null ? key : normUri(uriPart);
      newRoot = resource;
      if (frag === '') {
        target = resource;
      } else if (frag.startsWith('/')) {
        target = pointerLookup(resource, frag);
      } else {
        target = this.anchors.get(newBase + '#' + frag);
      }
    }

    if (target === undefined) return undefined;
    return { schema: target, base: newBase, docRoot: newRoot };
  }
}

// ---------------------------------------------------------------------------
// createValidatorClass
// ---------------------------------------------------------------------------

export function createValidatorClass({ name, draft, keywords, metaSchema }) {
  const legacyRef = draft === 4 || draft === 6 || draft === 7;

  // Core validation of `instance` against (sub)`schema`.
  // state: { validator, resolver, base, docRoot, strictRefs, active }
  function run(state, instance, schema, path, schemaPath) {
    if (schema === true) return [];
    if (schema === false) return [makeError(path, schemaPath)];
    if (!isPlainObject(schema)) {
      // Python crashes (AttributeError / resolution errors) when a schema
      // position holds a non-object, non-boolean value.
      throw new TypeError('schema is not of type object/boolean');
    }

    // Cycle guard: the same (schema, instance) pair on the active stack
    // means infinite $ref recursion — Python dies with RecursionError.
    let seen = state.active.get(schema);
    if (seen === undefined) {
      seen = new Set();
      state.active.set(schema, seen);
    }
    if (seen.has(instance)) {
      throw new Error('RecursionError: circular $ref detected');
    }
    seen.add(instance);
    try {
      return runInner(state, instance, schema, path, schemaPath);
    } finally {
      seen.delete(instance);
    }
  }

  function runInner(state, instance, schema, path, schemaPath) {
    let base = state.base;
    let docRoot = state.docRoot;
    const id =
      typeof schema.$id === 'string'
        ? schema.$id
        : legacyRef && typeof schema.id === 'string' && !schema.id.startsWith('#')
          ? schema.id
          : null;
    if (id) {
      const abs = resolveUri(id, base);
      if (abs) {
        base = normUri(abs);
        docRoot = schema;
      }
    }
    const sub = { ...state, base, docRoot };

    const errors = [];

    if (Object.prototype.hasOwnProperty.call(schema, '$ref')) {
      const refErrors = resolveRefLike(sub, instance, schema.$ref, path, schemaPath.concat('$ref'));
      if (legacyRef) return refErrors; // drafts 4/6/7: $ref eats all siblings
      errors.push(...refErrors); // 2019/2020: $ref AND siblings
    }
    if (!legacyRef) {
      if (typeof schema.$recursiveRef === 'string') {
        errors.push(
          ...resolveRefLike(sub, instance, schema.$recursiveRef, path, schemaPath.concat('$recursiveRef')),
        );
      }
      if (typeof schema.$dynamicRef === 'string') {
        errors.push(
          ...resolveRefLike(sub, instance, schema.$dynamicRef, path, schemaPath.concat('$dynamicRef')),
        );
      }
    }

    const ctx = makeCtx(sub, path, schemaPath);
    for (const key of Object.keys(schema)) {
      if (key === '$ref' || key === '$recursiveRef' || key === '$dynamicRef') continue;
      const fn = keywords[key];
      if (fn === undefined) continue; // unknown / unsupported keyword: ignore
      const errs = fn(ctx, schema[key], instance, schema);
      if (errs) for (const e of errs) errors.push(e);
    }
    return errors;
  }

  function resolveRefLike(state, instance, ref, path, schemaPath) {
    if (typeof ref !== 'string') {
      if (state.strictRefs) throw new TypeError('$ref value is not a string');
      return []; // permissive mode (checkSchema)
    }
    const target = state.resolver.resolve(ref, state.base, state.docRoot);
    if (target === undefined) {
      if (state.strictRefs) throw new Error(`Unresolvable: ${ref}`);
      return []; // permissive mode: never crash checkSchema on dangling refs
    }
    return run(
      { ...state, base: target.base, docRoot: target.docRoot },
      instance,
      target.schema,
      path,
      schemaPath,
    );
  }

  function makeCtx(state, path, schemaPath) {
    return {
      draft,
      validator: state.validator,
      isValid(instance, subschema) {
        return run(state, instance, subschema, path, schemaPath).length === 0;
      },
      descend(instance, subschema, instancePathSuffix = [], schemaPathSuffix = []) {
        return run(
          state,
          instance,
          subschema,
          path.concat(instancePathSuffix),
          schemaPath.concat(schemaPathSuffix),
        );
      },
    };
  }

  const Validator = class {
    constructor(schema) {
      // Python crashes constructing a validator over a boolean root schema.
      if (typeof schema === 'boolean') {
        throw new TypeError('Boolean root schemas are not supported');
      }
      this.schema = schema;
      this._resolvers = new Map(); // root schema object -> Resolver
    }

    _resolverFor(root) {
      let resolver = this._resolvers.get(root);
      if (resolver === undefined) {
        resolver = new Resolver(isPlainObject(root) ? root : {});
        this._resolvers.set(root, resolver);
      }
      return resolver;
    }

    _topState(root, strictRefs) {
      const resolver = this._resolverFor(root);
      return {
        validator: this,
        resolver,
        base: resolver.rootBase,
        docRoot: isPlainObject(root) ? root : {},
        strictRefs,
        active: new Map(),
      };
    }

    iterErrors(instance) {
      return run(this._topState(this.schema, true), instance, this.schema, [], []);
    }

    isValid(instance) {
      return this.iterErrors(instance).length === 0;
    }

    // Validate `schema` against this draft's meta-schema, using this class's
    // own keyword set (mirroring Python's cls.check_schema). Unresolvable
    // refs inside the meta-schema are treated as valid — a false crash on a
    // valid schema is the worst outcome.
    checkSchema(schema) {
      const errors = run(this._topState(metaSchema, false), schema, metaSchema, [], []);
      if (errors.length > 0) {
        const err = new Error(`SchemaError: schema is invalid against the ${name} meta-schema`);
        err.name = 'SchemaError';
        throw err;
      }
      return null;
    }

    evolve({ schema } = {}) {
      return new Validator(schema);
    }
  };

  Object.defineProperty(Validator, 'name', { value: name, configurable: true });
  return Validator;
}

// Assembly of the five draft validator classes from the keyword modules,
// the engine, and the per-draft meta-schemas.

import { createValidatorClass } from './engine.mjs';
import { keywords as core } from './keywords/core.mjs';
import { keywords as numeric } from './keywords/numeric.mjs';
import { keywords as string } from './keywords/string.mjs';
import { keywords as array } from './keywords/array.mjs';
import { keywords as object } from './keywords/object.mjs';
import { keywords as applicator } from './keywords/applicator.mjs';
import { META4, META6, META7, META2019, META2020 } from './meta/schemas.mjs';

// Union of every implemented keyword, regardless of which module owns it.
const ALL = { ...core, ...numeric, ...string, ...array, ...object, ...applicator };

function take(...names) {
  const out = {};
  for (const n of names) {
    if (ALL[n] !== undefined) out[n] = ALL[n];
  }
  return out;
}

// draft4: no const/contains/propertyNames/if/then/else/prefixItems/dependent*/
const DRAFT4 = take(
  'type', 'enum',
  'minimum', 'maximum', 'exclusiveMinimum', 'exclusiveMaximum', 'multipleOf',
  'minLength', 'maxLength', 'pattern',
  'items', 'additionalItems', 'minItems', 'maxItems', 'uniqueItems',
  'properties', 'patternProperties', 'additionalProperties',
  'required', 'minProperties', 'maxProperties', 'dependencies',
  'allOf', 'anyOf', 'oneOf', 'not',
);

// draft6: draft4 + const, contains, propertyNames
// (exclusiveMinimum/exclusiveMaximum are numbers here — the numeric module
// dispatches on ctx.draft)
const DRAFT6 = { ...DRAFT4, ...take('const', 'contains', 'propertyNames') };

// draft7: draft6 + if/then/else
const DRAFT7 = { ...DRAFT6, ...take('if', 'then', 'else') };

// draft2019: draft7 + dependent*, min/maxContains, unevaluated*
// (dependencies still honored)
const DRAFT2019 = {
  ...DRAFT7,
  ...take(
    'dependentRequired', 'dependentSchemas',
    'minContains', 'maxContains',
    'unevaluatedProperties', 'unevaluatedItems',
  ),
};

// draft2020: draft2019 - dependencies/additionalItems + prefixItems
const DRAFT2020 = { ...DRAFT2019, ...take('prefixItems') };
delete DRAFT2020.dependencies;
delete DRAFT2020.additionalItems;

export const Draft4Validator = createValidatorClass({
  name: 'Draft4Validator',
  draft: 4,
  keywords: DRAFT4,
  metaSchema: META4,
});

export const Draft6Validator = createValidatorClass({
  name: 'Draft6Validator',
  draft: 6,
  keywords: DRAFT6,
  metaSchema: META6,
});

export const Draft7Validator = createValidatorClass({
  name: 'Draft7Validator',
  draft: 7,
  keywords: DRAFT7,
  metaSchema: META7,
});

export const Draft201909Validator = createValidatorClass({
  name: 'Draft201909Validator',
  draft: 2019,
  keywords: DRAFT2019,
  metaSchema: META2019,
});

export const Draft202012Validator = createValidatorClass({
  name: 'Draft202012Validator',
  draft: 2020,
  keywords: DRAFT2020,
  metaSchema: META2020,
});

import { createValidatorClass } from '/output/lib/engine.mjs';
import { makeError } from '/output/lib/errors.mjs';

// --- stub keyword fns (mimic contract behavior) ---
const typeFn = (ctx, value, instance) => {
  const ok = (t) => {
    switch (t) {
      case 'integer': return typeof instance === 'number' && Number.isInteger(instance);
      case 'number': return typeof instance === 'number';
      case 'string': return typeof instance === 'string';
      case 'object': return typeof instance === 'object' && instance !== null && !Array.isArray(instance);
      case 'array': return Array.isArray(instance);
      case 'boolean': return typeof instance === 'boolean';
      case 'null': return instance === null;
      default: throw new Error('UnknownType: ' + t);
    }
  };
  const types = Array.isArray(value) ? value : [value];
  return types.some(ok) ? [] : [makeError()];
};
const propertiesFn = (ctx, value, instance) => {
  if (typeof instance !== 'object' || instance === null || Array.isArray(instance)) return [];
  const errs = [];
  for (const [k, sub] of Object.entries(value)) {
    if (k in instance) errs.push(...ctx.descend(instance[k], sub, [k], ['properties', k]));
  }
  return errs;
};
const itemsFn = (ctx, value, instance) => {
  if (!Array.isArray(instance)) return [];
  const errs = [];
  instance.forEach((el, i) => errs.push(...ctx.descend(el, value, [i], ['items'])));
  return errs;
};
const minItemsFn = (ctx, value, instance) =>
  Array.isArray(instance) && instance.length < value ? [makeError()] : [];

const kw = { type: typeFn, properties: propertiesFn, items: itemsFn, minItems: minItemsFn };

