    items: { $ref: '#' },
  },
};
const additionalPropertiesFn = (ctx, value, instance) => {
  if (typeof instance !== 'object' || instance === null || Array.isArray(instance)) return [];
  const errs = [];
  const props = ctx && instance; // simplified: all keys extra (no properties tracking in stub)
  for (const k of Object.keys(instance)) errs.push(...ctx.descend(instance[k], value, [k], ['additionalProperties']));
  return errs;
};
const metaKw = { ...kw, additionalProperties: additionalPropertiesFn };

const mk = (draft) => createValidatorClass({ name: 'V' + draft, draft, keywords: draft === 'meta' ? metaKw : kw, metaSchema: miniMeta });
const [V4, V6, V7, V19, V20] = [4, 6, 7, 2019, 2020].map(mk);

let pass = 0, fail = 0;
function eq(actual, expected, label) {
  const a = JSON.stringify(actual), e = JSON.stringify(expected);
  if (a === e) { pass++; } else { fail++; console.log(`FAIL ${label}: got ${a} want ${e}`); }
}

// 1. $ref with sibling type — legacy short-circuits, modern evaluates both
