eq([V4, V6, V7, V19, V20].map(V => new V(s1).iterErrors('x').length), [1, 1, 1, 2, 2], '$ref+sibling counts');
eq([V4, V6, V7, V19, V20].map(V => new V(s1).isValid('x')), [false, false, false, false, false], '$ref+sibling valid');

// 2. $defs ref, all drafts
