eq([V4, V6, V7, V19, V20].map(V => new V(s2).iterErrors('x').length), [1, 1, 1, 1, 1], '$defs counts');
eq([V4, V6, V7, V19, V20].map(V => new V(s2).iterErrors(3).length), [0, 0, 0, 0, 0], '$defs valid');

