const s4b = { properties: { a: true } };
eq(new V20(s4b).iterErrors({ a: 1 }).length, 0, 'true subschema');

// 5. self ref -> throws
try { new V7({ $ref: '#' }).isValid(1); eq('no-throw', 'throw', 'self-ref'); } catch { pass++; }

// 6. missing ref -> throws
try { new V7({ $ref: '#/definitions/missing' }).isValid(1); eq('no-throw', 'throw', 'missing ref'); } catch { pass++; }

// 7. boolean root -> constructor throws
for (const V of [V4, V6, V7, V19, V20]) {
