}

// 8. evolve
const v7 = new V7({ type: 'integer' });
const ev = v7.evolve({ schema: { type: 'string' } });
eq([ev instanceof V7, ev.isValid('x'), ev.isValid(1), v7.isValid(1)], [true, true, false, true], 'evolve');

// 9. ctx.isValid and ctx.validator
eq(typeof v7.isValid, 'function', 'api surface');
{
  const kwX = { type: typeFn, not: (ctx, val, inst) => ctx.isValid(inst, val) ? [makeError()] : [] };
