  constructor(root, registerIds = true) {
    this.root = root;
    this.registerIds = registerIds;
    this.ids = new Map(); // normalized absolute $id -> schema object
    this.anchors = new Map(); // normalized absolute base + '#' + name -> schema
    this.rootBase = '';
    if (registerIds) {
      const id = this._schemaId(root);
      if (id) {
        const abs = resolveUri(id, '');
        this.rootBase = normUri(abs || id);
      }
    }
    this._walk(root, this.rootBase);
  }

  _schemaId(schema) {
    if (!isPlainObject(schema)) return null;
    if (typeof schema.$id === 'string') return schema.$id;
    // legacy draft-04 style "id"
    if (typeof schema.id === 'string') return schema.id;
    return null;
  }

  _walk(node, base) {
    if (Array.isArray(node)) {
      for (const item of node) this._walk(item, base);
      return;
    }
    if (!isPlainObject(node)) return;

    const id = this._schemaId(node);
    if (id) {
      if (id.startsWith('#')) {
        // legacy fragment id: "id": "#foo" declares anchor foo
        this.anchors.set(base + id, node);
      } else if (this.registerIds) {
        const abs = resolveUri(id, base);
        if (abs) {
          base = normUri(abs);
          this.ids.set(base, node);
          // an $id with a fragment (".../x.json#foo") also declares an anchor
          const hash = abs.indexOf('#');
          if (hash !== -1 && hash < abs.length - 1) {
            this.anchors.set(normUri(abs.slice(0, hash)) + abs.slice(hash), node);
          }
        }
      }
    }

